package com.technova.rest;
import com.technova.model.*; import com.technova.repo.*; import com.technova.report.ReportService; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api") public class ApiController {private final ProductoRepository pr; private final CategoriaRepository cr; private final ClienteRepository clr; private final PedidoRepository per; private final ReportService reports; public ApiController(ProductoRepository p,CategoriaRepository c,ClienteRepository cl,PedidoRepository pe,ReportService r){pr=p;cr=c;clr=cl;per=pe;reports=r;}
@GetMapping("/public/productos") public List<Producto> productos(){return pr.findAll();} @GetMapping("/public/categorias") public List<Categoria> categorias(){return cr.findAll();}
@GetMapping("/admin/dashboard") public Map<String,Object> dashboard(){long stockBajo=pr.findAll().stream().filter(p->p.getStock()!=null&&p.getStockMinimo()!=null&&p.getStock()<=p.getStockMinimo()).count();return Map.of("productos",pr.count(),"clientes",clr.count(),"pedidos",per.count(),"stockBajo",stockBajo);}
@GetMapping("/admin/reportes/ventas.csv") public ResponseEntity<byte[]> csv(){return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=ventas.csv").contentType(MediaType.parseMediaType("text/csv")).body(reports.ventasCsv());}
@GetMapping("/admin/reportes/ventas.pdf") public ResponseEntity<byte[]> pdf(){return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=ventas.pdf").contentType(MediaType.APPLICATION_PDF).body(reports.ventasPdf());}
@GetMapping("/admin/reportes/productos.xlsx") public ResponseEntity<byte[]> xlsx() throws Exception{return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=productos.xlsx").contentType(MediaType.parseMediaType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")).body(reports.productosExcel());}}
